  const recentes = S.contagens.filter((c) => fechadaStatus(c.status)).sort((a, b) => (b.finalizadoEm || 0) - (a.finalizadoEm || 0)).slice(0, 3);
  const nProd = [...S.produtos.values()].filter((p) => p.ativo !== false).length;
